insert into public.events ("event_date", "start_time", "end_time", "venue", "fee", "deadline", "coordinator_name", "coordinator_phone", "coordinator_email", "registration_open", "visible", "poster_url", "is_sample", "id", "tagline", "participation", "team_min", "team_max", "capacity", "rules", "eligibility", "extra_questions", "sort_order", "slug", "name", "category", "tier", "short_description", "description") values ('2026-12-02', '', '', 'Mithibai College · room TBA', null, '2026-11-30T23:59:00+05:30', 'Aditya Dubey / Subha Nandula', '+91 91372 84809', 'animaux.zoology@gmail.com', true, true, '', false, 'e1000000-0000-4000-8000-000000000001', 'The flagship investigation of ANIMAUX''26.', 'team', 4, 5, 5, '["Format: team-based treasure hunt and escape-room investigation.","Participation: 4–5 teams of 4–5 members each.","Duration: approximately 45 minutes per session.","One continuous investigation combining clue-hunting, puzzles and case-solving.","Evidence must be collected and labelled correctly — mishandled clues may be declared compromised."]'::jsonb, '', '[]'::jsonb, 1, 'the-last-trace', 'The Last Trace', 'competition', 'main', 'An endangered animal found dead under suspicious circumstances. 45 minutes to hunt clues, decode forensic reports and crack the case.', 'The forest holds a secret — and your team has just 45 minutes to uncover it. An endangered animal has been found dead under suspicious circumstances, leaving behind scattered clues, conflicting accounts, and a trail that demands a closer look. Enter The Last Trace, the flagship event of Animaux 2026, where the chase of a treasure hunt meets the suspense of an escape room in a wildlife-forensics investigation.
insert into public.events ("event_date", "start_time", "end_time", "venue", "fee", "deadline", "coordinator_name", "coordinator_phone", "coordinator_email", "registration_open", "visible", "poster_url", "is_sample", "id", "tagline", "participation", "team_min", "team_max", "capacity", "rules", "eligibility", "extra_questions", "sort_order", "slug", "name", "category", "tier", "short_description", "description") values ('2026-12-02', '', '', 'Mithibai College · room TBA', null, '2026-11-30T23:59:00+05:30', 'Aditya Dubey / Subha Nandula', '+91 91372 84809', 'animaux.zoology@gmail.com', true, true, '', false, 'e1000000-0000-4000-8000-000000000002', 'Follow the Clues. Beat the Clock.', 'team', 4, 8, null, '["Format: team-based forensic station relay.","Participation: 4–8 members per team.","Station-based progression featuring four task types."]'::jsonb, '', '[]'::jsonb, 2, 'trace-evidence-relay', 'Trace Evidence Relay', 'competition', 'main', 'A fast-paced race through hands-on forensic checkpoints: soil pH matching, fingerprint lifting, mock fur comparison and chemical colour tests.', 'A little soil, a stray strand of fur, an almost invisible fingerprint — could you spot the clues that others overlook? Trace Evidence Relay sends your team through a series of hands-on forensic checkpoints, each testing a different investigative skill. Match soil samples using pH tests, lift fingerprints, compare mock fur samples, and interpret colour changes in a simulated chemical test.
insert into public.events ("event_date", "start_time", "end_time", "venue", "fee", "deadline", "coordinator_name", "coordinator_phone", "coordinator_email", "registration_open", "visible", "poster_url", "is_sample", "id", "tagline", "participation", "team_min", "team_max", "capacity", "rules", "eligibility", "extra_questions", "sort_order", "slug", "name", "category", "tier", "short_description", "description") values ('2026-12-02', '', '', 'Mithibai College · room TBA', null, '2026-11-30T23:59:00+05:30', 'Aditya Dubey / Subha Nandula', '+91 91372 84809', 'animaux.zoology@gmail.com', true, true, '', false, 'e1000000-0000-4000-8000-000000000003', 'Pitch for the Planet. Negotiate for the Wild.', 'team', 3, 5, null, '["Format: team-based eco-startup pitch competition.","Participation: 3–5 members per team; 8–10 teams are shortlisted for the live round.","Rounds: shortlisting → live pitches with questions and simulated negotiations → surprise challenge for the top three teams."]'::jsonb, '', '[{"id":"idea","label":"Your startup idea in one or two lines","type":"textarea","required":true}]'::jsonb, 3, 'wild-shark-tank', 'Wild Shark Tank: Eco-Startup Pitch', 'competition', 'main', 'Pitch a business, product or technology that tackles a wildlife or environmental challenge — and survive the Sharks’ questions.', 'The wild has problems. Your team might have the next big solution. Step into Wild Shark Tank, where conservation meets entrepreneurship and bold ideas face some sharp questions. Develop a business, product, or technology that addresses a wildlife or environmental challenge, then convince a panel of “Sharks” that your solution deserves their backing.
insert into public.events ("event_date", "start_time", "end_time", "venue", "fee", "deadline", "coordinator_name", "coordinator_phone", "coordinator_email", "registration_open", "visible", "poster_url", "is_sample", "id", "tagline", "participation", "team_min", "team_max", "capacity", "rules", "eligibility", "extra_questions", "sort_order", "slug", "name", "category", "tier", "short_description", "description") values ('2026-12-02', '', '', 'Mithibai College · room TBA', null, '2026-11-30T23:59:00+05:30', 'Aditya Dubey / Subha Nandula', '+91 91372 84809', 'animaux.zoology@gmail.com', true, true, '', false, 'e1000000-0000-4000-8000-000000000004', 'Protect the Sanctuary. Suspect Everyone.', 'individual', 1, 1, null, '["Format: group-based social-deduction game with secret Ranger and Poacher roles.","Rangers win by banishing every Poacher; Poachers win by matching the Rangers’ numbers or collapsing the Fund."]'::jsonb, 'Register individually. Group sizes and limits to be announced.', '[]'::jsonb, 4, 'the-poachers-tale', 'The Poacher’s Tale', 'game', 'main', 'Rangers build the Sanctuary Fund while secret Poachers work against them. Tell true or tall wildlife tales, cross-examine, and vote at the Campfire Council.', 'Welcome to the sanctuary, where everyone claims to be a protector — but not everyone is telling the truth. In The Poacher’s Tale, Rangers work together to complete missions and build a shared Sanctuary Fund while secret Poachers hide among them, waiting for their chance to strike. Every conversation could reveal a clue, conceal a lie, or turn an ally into your prime suspect.
insert into public.events ("event_date", "start_time", "end_time", "venue", "fee", "deadline", "coordinator_name", "coordinator_phone", "coordinator_email", "registration_open", "visible", "poster_url", "is_sample", "id", "tagline", "participation", "team_min", "team_max", "capacity", "rules", "eligibility", "extra_questions", "sort_order", "slug", "name", "category", "tier", "short_description", "description") values ('2026-12-02', '', '', 'Mithibai College · room TBA', null, '2026-11-30T23:59:00+05:30', 'Aditya Dubey / Subha Nandula', '+91 91372 84809', 'animaux.zoology@gmail.com', true, true, '', false, 'e1000000-0000-4000-8000-000000000005', 'Limited Ground. Changing Rules. One Team to Save.', 'team', 4, 5, 8, '["Format: team-based migration and survival challenge.","Participation: 6–8 teams of 4–5 members each.","Animal-call signals change the rules mid-round; finalists carry a toy baby animal to safety."]'::jsonb, '', '[]'::jsonb, 5, 'flood-zone', 'Flood Zone: Survive the Wild', 'game', 'main', 'Safe ground is shrinking. Cross a simulated danger zone on limited platforms while animal-call signals change the rules — leave no one behind.', 'The route ahead is dangerous, safe ground is limited, and your team must find a way across. Flood Zone: Survive the Wild places participants in a simulated flood, fire, or trap zone where a handful of safe platforms is all that stands between a clever crossing and a failed plan. Choose your moves carefully, shift your platforms forward, and keep every teammate in the picture.
insert into public.events ("event_date", "start_time", "end_time", "venue", "fee", "deadline", "coordinator_name", "coordinator_phone", "coordinator_email", "registration_open", "visible", "poster_url", "is_sample", "id", "tagline", "participation", "team_min", "team_max", "capacity", "rules", "eligibility", "extra_questions", "sort_order", "slug", "name", "category", "tier", "short_description", "description") values ('2026-12-02', '', '', 'Mithibai College · room TBA', null, '2026-11-30T23:59:00+05:30', 'Aditya Dubey / Subha Nandula', '+91 91372 84809', 'animaux.zoology@gmail.com', true, true, '', false, 'e1000000-0000-4000-8000-000000000006', 'Trust Your Knowledge. Earn Your Next Move.', 'individual', 1, 1, null, '["Format: individual question-and-step game.","Countdown-based gameplay."]'::jsonb, '', '[]'::jsonb, 6, '7-steps', '7 Steps', 'quiz', 'main', 'The counter has turned away. Answer right to step forward, wrong to step back — how far can you get before they turn around?', 'The counter has turned away, the countdown has begun, and every answer could change your position. In 7 Steps, participants line up behind a volunteer facing backwards while other volunteers put their knowledge to the test. A correct answer earns you one step forward; a wrong answer sends you one step back. There’s no team to carry you through this one — your progress rests on your own answers.
insert into public.events ("event_date", "start_time", "end_time", "venue", "fee", "deadline", "coordinator_name", "coordinator_phone", "coordinator_email", "registration_open", "visible", "poster_url", "is_sample", "id", "tagline", "participation", "team_min", "team_max", "capacity", "rules", "eligibility", "extra_questions", "sort_order", "slug", "name", "category", "tier", "short_description", "description") values ('2026-12-02', '', '', 'Mithibai College · room TBA', null, '2026-11-30T23:59:00+05:30', 'Aditya Dubey / Subha Nandula', '+91 91372 84809', 'animaux.zoology@gmail.com', true, true, '', false, 'e1000000-0000-4000-8000-000000000007', 'Every picture has a story — what will yours reveal?', 'individual', 1, 1, null, '[]'::jsonb, 'Details to be announced.', '[{"id":"photo","label":"Upload your photograph (JPG, PNG or WebP · up to 10 MB)","type":"file","required":true},{"id":"caption","label":"Title or caption for your photo","type":"text","required":false}]'::jsonb, 7, 'shutter-safari', 'Shutter Safari: Photography Competition', 'creative', 'main', 'Capture the beauty, mystery and unexpected details of the natural world — and upload your photograph when you register.', 'Every picture has a story — what will yours reveal? Capture the beauty, mystery, and unexpected details of the natural world through your lens. From a bird in motion to the tiny life hidden beneath a leaf, turn an ordinary moment into an extraordinary frame.
insert into public.events ("event_date", "start_time", "end_time", "venue", "fee", "deadline", "coordinator_name", "coordinator_phone", "coordinator_email", "registration_open", "visible", "poster_url", "is_sample", "id", "tagline", "participation", "team_min", "team_max", "capacity", "rules", "eligibility", "extra_questions", "sort_order", "slug", "name", "category", "tier", "short_description", "description") values ('2026-12-02', '', '', 'Mithibai College · room TBA', null, '2026-11-30T23:59:00+05:30', 'Aditya Dubey / Subha Nandula', '+91 91372 84809', 'animaux.zoology@gmail.com', true, true, '', false, 'e1000000-0000-4000-8000-000000000008', 'Small canvas, wild possibilities!', 'individual', 1, 1, null, '[]'::jsonb, 'Details to be announced.', '[]'::jsonb, 8, 'strokes-of-wild', 'Strokes of Wild: Coaster for Conservation', 'creative', 'main', 'Turn a simple coaster into a colourful celebration of nature — animal designs, leafy patterns, marine scenes or a conservation message.', 'Small canvas, wild possibilities! Turn a simple coaster into a colourful celebration of nature with animal-inspired designs, leafy patterns, marine scenes, or a conservation message close to your heart. Experiment with colours and details to create something that’s both useful and uniquely yours.
