insert into public.faqs ("id", "question", "answer", "visible", "sort_order") values ('fa000000-0000-4000-8000-000000000001', 'How do I register?', 'Open the Events page, pick one of the 8 main events and press “Register Now”. Fill in your name, college, year and contact number (plus your team, for team events). You instantly get a unique registration ID on screen — no account needed.', true, 0) on conflict (id) do update set "question" = excluded."question", "answer" = excluded."answer", "visible" = excluded."visible", "sort_order" = excluded."sort_order";
insert into public.faqs ("id", "question", "answer", "visible", "sort_order") values ('fa000000-0000-4000-8000-000000000002', 'Can I take part in more than one event?', 'Yes. Register separately for each event — the form remembers your details on your phone, so the next one takes seconds. Event timings will be announced; we’ll try to avoid clashes.', true, 1) on conflict (id) do update set "question" = excluded."question", "answer" = excluded."answer", "visible" = excluded."visible", "sort_order" = excluded."sort_order";
insert into public.faqs ("id", "question", "answer", "visible", "sort_order") values ('fa000000-0000-4000-8000-000000000003', 'Can students from other colleges participate?', 'ANIMAUX welcomes investigators from across campuses. Check each event page for any eligibility notes, or call the coordinators to confirm.', true, 2) on conflict (id) do update set "question" = excluded."question", "answer" = excluded."answer", "visible" = excluded."visible", "sort_order" = excluded."sort_order";
insert into public.faqs ("id", "question", "answer", "visible", "sort_order") values ('fa000000-0000-4000-8000-000000000004', 'Are there registration fees?', 'Fees, if any, are shown on each event card. “Fee: TBA” means it hasn’t been announced yet.', true, 3) on conflict (id) do update set "question" = excluded."question", "answer" = excluded."answer", "visible" = excluded."visible", "sort_order" = excluded."sort_order";
insert into public.faqs ("id", "question", "answer", "visible", "sort_order") values ('fa000000-0000-4000-8000-000000000005', 'How do team registrations work?', 'The team leader registers once for the whole team: a team name, plus each member’s name. Team sizes and team limits (for example, 5 teams for The Last Trace) are shown on each event.', true, 4) on conflict (id) do update set "question" = excluded."question", "answer" = excluded."answer", "visible" = excluded."visible", "sort_order" = excluded."sort_order";
insert into public.faqs ("id", "question", "answer", "visible", "sort_order") values ('fa000000-0000-4000-8000-000000000006', 'What are mini events?', 'Six quick, on-the-spot games — Wildlife Pictionary, Wild Aim, Wild Eye, Fingerprint Paintings, Who Am I? and the Memory Game. Just walk in on 2 December; no online registration needed.', true, 5) on conflict (id) do update set "question" = excluded."question", "answer" = excluded."answer", "visible" = excluded."visible", "sort_order" = excluded."sort_order";
insert into public.faqs ("id", "question", "answer", "visible", "sort_order") values ('fa000000-0000-4000-8000-000000000007', 'How do I submit my photo for Shutter Safari?', 'Upload it in the registration form for Shutter Safari (JPG, PNG or WebP, up to 10 MB). Large photos are resized automatically before upload.', true, 6) on conflict (id) do update set "question" = excluded."question", "answer" = excluded."answer", "visible" = excluded."visible", "sort_order" = excluded."sort_order";
insert into public.faqs ("id", "question", "answer", "visible", "sort_order") values ('fa000000-0000-4000-8000-000000000008', 'Who do I contact with questions?', 'Call Aditya (+91 91372 84809) or Subha (+91 84540 26143), email animaux.zoology@gmail.com, or use the help desk form on the Contact page.', true, 7) on conflict (id) do update set "question" = excluded."question", "answer" = excluded."answer", "visible" = excluded."visible", "sort_order" = excluded."sort_order";
insert into public.festival_settings (id, data) values (1, '{"name":"ANIMAUX","edition":"2026","theme":"Echoes of the Wild: The Survival Files","tagline":"Every footprint is a clue, every feather is evidence, and every species has a survival story.","manifesto":"The wilderness is your casebook. Follow the echoes, examine the evidence, and open The Survival Files!","startDate":"2026-12-02T09:00:00+05:30","endDate":"2026-12-02T18:00:00+05:30","datesConfirmed":true,"department":"Department of Zoology","college":"SVKM''s Mithibai College","address":"Mithibai College of Arts, Chauhan Institute of Science & Amrutben Jivanlal College of Commerce and Economics (Empowered Autonomous), Vile Parle (West), Mumbai 400056","mapEmbedUrl":"https://www.google.com/maps?q=Mithibai+College,+Vile+Parle+West,+Mumbai&output=embed","mapLink":"https://www.google.com/maps/search/?api=1&query=Mithibai+College+Vile+Parle+West+Mumbai","email":"animaux.zoology@gmail.com","phone":"+91 91372 84809","contacts":["Aditya Dubey | +91 91372 84809","Subha Nandula | +91 84540 26143"],"whatsapp":"","instagram":"","brochureUrl":"https://canva.link/nziclf8o20e187l","registrationsOpen":true,"guidelines":["Carry your college ID card and your ANIMAUX registration ID on 2 December.","Report to your event venue at least 15 minutes before it begins.","Team events are registered once, by the team leader, with every member''s name.","Mini events are on the spot — no online registration needed.","Crime-scene props and evidence are for investigation only — look, note, and don’t touch unless told.","The decision of the judges and organising committee is final."]}'::jsonb) on conflict (id) do update set data = excluded.data;
